metadata.orrery:spec:
# yaml-language-server: $schema=https://raw.githubusercontent.com/Sagargupta16/orrery/main/skills/orrery/references/diagram.schema.json
# Rendered with orrery (github.com/Sagargupta16/orrery):
#   orrery render docs/diagrams/ml-lifecycle.yaml -o docs/diagrams/ml-lifecycle -f svg --theme both
# Reviewed at README width: orrery review docs/diagrams/ml-lifecycle.yaml --width 880
title: Data and model lifecycle
subtitle: A weekly job publishes the data to the Hub; retraining is manual and ships only if it wins the backtest
direction: down
layout: { spacing: compact }
legend:
  dashed: Merged or committed by hand

groups:
  weekly: { type: box, label: Weekly GitHub Actions job, icon: logos:github-actions, evidence: .github/workflows/refresh-data.yml:8 }
  manual: { type: dashed, label: Manual retrain, evidence: CONTRIBUTING.md:13 }
  hub: { type: box, label: Hugging Face Hub, icon: logos:hugging-face-icon, evidence: scripts/publish_model.py:32 }

nodes:
  update: { icon: logos:python, label: update_data.py, note: "12,000 users, 95% retention floor", in: weekly, evidence: [scripts/update_data.py:72, scripts/update_data.py:46] }
  exportds: { icon: logos:python, label: export_dataset.py, note: Parquet split by user, in: weekly, evidence: [scripts/export_dataset.py:45, .github/workflows/refresh-data.yml:40] }
  backtest: { icon: tabler:chart-line, label: backtest.py, note: scores models/ on unseen users, in: weekly, evidence: [scripts/backtest.py:177, scripts/backtest.py:245] }
  pr: { icon: github:git-pull-request, label: Backtest PR, note: docs/backtest.md only, in: weekly, evidence: .github/workflows/refresh-data.yml:61 }
  graphql: { icon: logos:graphql, label: LeetCode GraphQL, note: leetcode.com/graphql, evidence: scripts/update_data.py:32 }
  dataset: { icon: tabler:table, label: Dataset repo, note: leetcode-contest-rating-changes, in: hub, evidence: scripts/export_dataset.py:191 }
  train: { icon: logos:tensorflow, label: train.py, note: "Keras, --data hub, --loss huber", in: manual, evidence: [scripts/train.py:102, CONTRIBUTING.md:22] }
  export: { icon: logos:python, label: export_model.py, note: Dense layers to NumPy arrays, in: manual, align: train, evidence: scripts/export_model.py:120 }
  weights: { icon: tabler:file-database, label: Model artifacts, note: "weights.npz, scaler.json, model.json", evidence: [scripts/export_model.py:35, scripts/publish_model.py:37] }
  modelrepo: { icon: tabler:package, label: Model repo, note: leetcode-rating-predictor, in: hub, evidence: scripts/publish_model.py:229 }
  serve: { icon: logos:fastapi-icon, label: FastAPI on Render, note: loads models/ at startup, align: weights, evidence: main.py:75 }
  ext: { icon: logos:chrome, label: Chrome extension, note: loads model.json daily, evidence: extension/background.js:27 }

edges:
  - weekly -> graphql: { label: contest histories, evidence: [scripts/update_data.py:109, scripts/backtest.py:221] }
  - update -> exportds: { label: data/data.json, evidence: scripts/update_data.py:457 }
  - exportds -> dataset: { label: Parquet, evidence: scripts/export_dataset.py:191 }
  - backtest -> pr: { label: docs/backtest.md, evidence: .github/workflows/refresh-data.yml:61 }
  - dataset --> train: { label: "--data hub", evidence: scripts/train.py:107 }
  - train -> export: { label: model.keras, evidence: scripts/train.py:223 }
  - export -> weights: { label: models/, evidence: scripts/export_model.py:35 }
  - weights --> serve: { label: committed if it wins, evidence: CONTRIBUTING.md:33 }
  - weights --> modelrepo: { label: publish_model.py, evidence: scripts/publish_model.py:229 }
  - modelrepo -> ext: { label: model.json, evidence: extension/core.js:8 }
